// Registers handlers, and prepends BaseURL to the paths, so that the paths
// can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.GET(baseURL+"/account", wrapper.GetAccount)
	router.POST(baseURL+"/admin/plans", wrapper.PostAdminPlans)
	router.POST(baseURL+"/auth/email/confirm", wrapper.PostAuthEmailConfirm)
	router.POST(baseURL+"/auth/email/start", wrapper.PostAuthEmailStart)
	router.POST(baseURL+"/auth/login", wrapper.PostAuthLogin)
	router.POST(baseURL+"/auth/logout", wrapper.PostAuthLogout)
	router.POST(baseURL+"/auth/portal", wrapper.PostAuthPortal)
	router.GET(baseURL+"/auth/portal/:sessionId", wrapper.GetAuthPortalSessionId)
	router.POST(baseURL+"/auth/refresh", wrapper.PostAuthRefresh)
	router.POST(baseURL+"/auth/register", wrapper.PostAuthRegister)
	router.GET(baseURL+"/billing", wrapper.GetBilling)
	router.POST(baseURL+"/billing/checkout", wrapper.PostBillingCheckout)
	router.POST(baseURL+"/billing/portal", wrapper.PostBillingPortal)
	router.GET(baseURL+"/healthz", wrapper.GetHealthz)
	router.GET(baseURL+"/me", wrapper.GetMe)
	router.GET(baseURL+"/plans", wrapper.GetPlans)
	router.GET(baseURL+"/readyz", wrapper.GetReadyz)
	router.GET(baseURL+"/subscription", wrapper.GetSubscription)
	router.POST(baseURL+"/subscription/checkout", wrapper.PostSubscriptionCheckout)
	router.POST(baseURL+"/subscriptions/cancel", wrapper.PostSubscriptionsCancel)
	router.GET(baseURL+"/subscriptions/me", wrapper.GetSubscriptionsMe)
	router.POST(baseURL+"/webhooks/:provider", wrapper.PostWebhooksProvider)

}

